import icontract
from typing import List


def erase_dups(xs: List[int]) -> List[int]:
    """The distinct values of xs, each kept at its first occurrence, in order."""
    out: List[int] = []
    for x in xs:
        if x not in out:
            out.append(x)
    return out


def product(xs: List[int]) -> int:
    """Product of all elements of xs (1 for the empty list)."""
    p = 1
    for x in xs:
        p *= x
    return p


@icontract.ensure(lambda arr, result: result == product(erase_dups(arr)))
def uniqueProduct(arr: List[int]) -> int:
    seen = set()
    result = 1
    for x in arr:
        if x not in seen:
            seen.add(x)
            result *= x
    return result
